import React, { useContext } from "react";
import noteContext from "../context/notes/noteContext";

const NoteStats = () => {
  const context = useContext(noteContext);
  const { noteStats, notes, getFilteredNotes, getAllTags } = context;

  const filteredNotes = getFilteredNotes();
  const totalTags = getAllTags().length;
  
  // Calculate additional stats
  const averageWordsPerNote = noteStats.totalNotes > 0 
    ? Math.round(noteStats.totalWords / noteStats.totalNotes) 
    : 0;

  const completedTodos = notes.reduce((acc, note) => {
    if (note.todoItems) {
      return acc + note.todoItems.filter(todo => todo.completed).length;
    }
    return acc;
  }, 0);

  const totalTodos = notes.reduce((acc, note) => {
    return acc + (note.todoItems ? note.todoItems.length : 0);
  }, 0);

  const notesWithImages = notes.filter(note => note.images && note.images.length > 0).length;
  const notesWithAttachments = notes.filter(note => note.attachments && note.attachments.length > 0).length;

  return (
    <div className="card mb-4">
      <div className="card-header">
        <h5 className="mb-0">
          <i className="fas fa-chart-bar me-2"></i>Note Statistics
        </h5>
      </div>
      <div className="card-body">
        <div className="row text-center">
          {/* Total Notes */}
          <div className="col-md-2 col-sm-4 col-6 mb-3">
            <div className="stat-item">
              <div className="stat-icon text-primary">
                <i className="fas fa-sticky-note fa-2x"></i>
              </div>
              <div className="stat-number h4 mb-1">{noteStats.totalNotes}</div>
              <div className="stat-label text-muted small">Total Notes</div>
            </div>
          </div>

          {/* Filtered Notes */}
          {filteredNotes.length !== noteStats.totalNotes && (
            <div className="col-md-2 col-sm-4 col-6 mb-3">
              <div className="stat-item">
                <div className="stat-icon text-info">
                  <i className="fas fa-filter fa-2x"></i>
                </div>
                <div className="stat-number h4 mb-1">{filteredNotes.length}</div>
                <div className="stat-label text-muted small">Filtered</div>
              </div>
            </div>
          )}

          {/* Total Words */}
          <div className="col-md-2 col-sm-4 col-6 mb-3">
            <div className="stat-item">
              <div className="stat-icon text-success">
                <i className="fas fa-font fa-2x"></i>
              </div>
              <div className="stat-number h4 mb-1">{noteStats.totalWords.toLocaleString()}</div>
              <div className="stat-label text-muted small">Total Words</div>
            </div>
          </div>

          {/* Average Words */}
          <div className="col-md-2 col-sm-4 col-6 mb-3">
            <div className="stat-item">
              <div className="stat-icon text-warning">
                <i className="fas fa-calculator fa-2x"></i>
              </div>
              <div className="stat-number h4 mb-1">{averageWordsPerNote}</div>
              <div className="stat-label text-muted small">Avg Words/Note</div>
            </div>
          </div>

          {/* Total Tags */}
          <div className="col-md-2 col-sm-4 col-6 mb-3">
            <div className="stat-item">
              <div className="stat-icon text-danger">
                <i className="fas fa-tags fa-2x"></i>
              </div>
              <div className="stat-number h4 mb-1">{totalTags}</div>
              <div className="stat-label text-muted small">Unique Tags</div>
            </div>
          </div>

          {/* Todo Progress */}
          {totalTodos > 0 && (
            <div className="col-md-2 col-sm-4 col-6 mb-3">
              <div className="stat-item">
                <div className="stat-icon text-purple">
                  <i className="fas fa-tasks fa-2x"></i>
                </div>
                <div className="stat-number h4 mb-1">{completedTodos}/{totalTodos}</div>
                <div className="stat-label text-muted small">Todos Done</div>
              </div>
            </div>
          )}
        </div>

        {/* Additional Stats Row */}
        <div className="row mt-3">
          <div className="col-12">
            <div className="d-flex flex-wrap justify-content-center gap-4">
              {/* Characters */}
              <div className="text-center">
                <small className="text-muted">Total Characters</small>
                <div className="fw-bold">{noteStats.totalCharacters.toLocaleString()}</div>
              </div>

              {/* Notes with Images */}
              {notesWithImages > 0 && (
                <div className="text-center">
                  <small className="text-muted">Notes with Images</small>
                  <div className="fw-bold">{notesWithImages}</div>
                </div>
              )}

              {/* Notes with Attachments */}
              {notesWithAttachments > 0 && (
                <div className="text-center">
                  <small className="text-muted">Notes with Attachments</small>
                  <div className="fw-bold">{notesWithAttachments}</div>
                </div>
              )}

              {/* Todo Completion Rate */}
              {totalTodos > 0 && (
                <div className="text-center">
                  <small className="text-muted">Todo Completion</small>
                  <div className="fw-bold">{Math.round((completedTodos / totalTodos) * 100)}%</div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Progress Bar for Todo Completion */}
        {totalTodos > 0 && (
          <div className="row mt-3">
            <div className="col-12">
              <small className="text-muted">Todo Progress:</small>
              <div className="progress mt-1" style={{ height: '8px' }}>
                <div
                  className="progress-bar bg-success"
                  role="progressbar"
                  style={{ width: `${(completedTodos / totalTodos) * 100}%` }}
                  aria-valuenow={completedTodos}
                  aria-valuemin="0"
                  aria-valuemax={totalTodos}
                ></div>
              </div>
            </div>
          </div>
        )}
      </div>

      <style jsx>{`
        .stat-item {
          padding: 10px;
          border-radius: 8px;
          transition: transform 0.2s;
        }
        .stat-item:hover {
          transform: translateY(-2px);
        }
        .stat-icon {
          margin-bottom: 8px;
        }
        .text-purple {
          color: #6f42c1 !important;
        }
      `}</style>
    </div>
  );
};

export default NoteStats;
